import {LIBRARY_REPORTS,REPORT_CATEGORIES,findLibraryReports} from './report-library-data.mjs';
import {isDate,today,shiftDate,csv} from './model.mjs';
import {teachers} from './teaching-data.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(rows,value='')=>rows.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
export function createReportLibraryUI(ui){
 let query='',category='',open=new Set(['Attendance','Class Attendance']),selected=null,result=null,running=false,serial=0;
 const $=s=>document.querySelector(s),favorite=id=>ui.state().favorites.includes(id);
 function card(r){return `<article class="library-report-card"><div class="library-report-icon" aria-hidden="true">▤</div><button class="favorite ${favorite(r.id)?'on':''}" data-action="library-favorite" data-id="${r.id}" aria-label="${favorite(r.id)?'Remove':'Add'} ${esc(r.title)} ${favorite(r.id)?'from':'to'} favourites" aria-pressed="${favorite(r.id)}">★</button><button class="library-report-open" data-action="library-open" data-id="${r.id}"><strong>${esc(r.title)}</strong><span>${esc(r.description)}</span></button><footer><span><b>Visibility:</b> All staff</span><span>Configure →</span></footer></article>`;}
 function paint(){
  if(!$('#library-results'))return;const matches=findLibraryReports(query,category),favs=matches.filter(r=>favorite(r.id));
  $('#library-favorites').innerHTML=favs.length?`<div class="library-cards">${favs.map(card).join('')}</div>`:'<p class="muted">Star a report to keep it here.</p>';
  $('#library-count').textContent=matches.length+' of '+LIBRARY_REPORTS.length+' reports';
  $('#library-results').innerHTML=REPORT_CATEGORIES.map(name=>{const rows=matches.filter(r=>r.category===name);return rows.length?`<details class="library-category" data-category="${esc(name)}" ${query||category||open.has(name)?'open':''}><summary>${esc(name)} <span>(${rows.length})</span></summary><div class="library-cards">${rows.map(card).join('')}</div></details>`:'';}).join('')||'<p class="empty">No reports match this search.</p>';
 }
 function page(){setTimeout(paint,0);return `<div class="library-heading"><div><div class="eyebrow">REPORTING</div><h1>Reports library</h1></div><span>49 school reports</span></div><section class="library-favorite-section"><h2>Favourite reports</h2><div id="library-favorites"></div></section><div class="library-toolbar"><label class="sr-only" for="library-search">Search reports</label><input type="search" id="library-search" placeholder="Search reports…" value="${esc(query)}"><label class="sr-only" for="library-category">Report category</label><select id="library-category">${options([['','All categories'],...REPORT_CATEGORIES.map(c=>[c,c])],category)}</select><button class="btn small" data-action="library-expand">Expand all</button><button class="btn small" data-action="library-collapse">Collapse all</button></div><div class="library-status"><span id="library-count" role="status">49 reports</span><small>Use saved data for your allocated students. Star reports for quick access.</small></div><div id="library-results"></div><details class="library-history"><summary>Recent exports (${ui.state().reportHistory.length})</summary>${ui.state().reportHistory.slice(0,10).map(r=>`<p><strong>${esc(r.title)}</strong><br><small>${esc(r.detail)} · ${esc(r.at)}</small></p>`).join('')||'<p class="muted">No exports yet.</p>'}</details>`;}
 function classChoices(year=''){return ui.classes().filter(c=>!year||String(c.year)===year);}
 function studentChoices(year='',classId=''){const ids=classId?new Set(classChoices(year).find(c=>c.id===classId)?.studentIds||[]):null;return ui.students().filter(s=>(!year||String(s.year)===year)&&(!ids||ids.has(s.id)));}
 function configure(id){
  selected=LIBRARY_REPORTS.find(r=>r.id===id);if(!selected)return;result=null;serial++;running=false;
  const day=ui.testDate()||today(),academicStart=(Number(day.slice(0,4))-(Number(day.slice(5,7))<8?1:0))+'-08-01',defaultFrom=/^(grade|average|final|published|missing|assignments|progress|comments)/.test(selected.kind)?academicStart:day.slice(0,7)+'-01',yearRows=[...new Map(ui.students().map(s=>[String(s.year),s.yearLabel])).entries()];
  ui.openDialog(selected.title,`<p>${esc(selected.description)}</p><div class="library-filter-grid"><label class="field"><span>Year</span><select id="library-year">${options([['','All years'],...yearRows])}</select></label><label class="field"><span>Teaching class</span><select id="library-class">${options([['','All allocated classes'],...classChoices().map(c=>[c.id,c.name])])}</select></label><label class="field"><span>Student</span><select id="library-student">${options([['','All selected students'],...studentChoices().map(s=>[s.id,s.name+' · '+s.groupName])])}</select></label><label class="field"><span>Teacher</span><select id="library-teacher">${options(ui.teacher().role==='report-reviewer'?[['','All selected teachers'],...teachers.map(t=>[t.id,t.name])]:[[ui.teacher().id,ui.teacher().name]],ui.teacher().role==='report-reviewer'?'':ui.teacher().id)}</select></label><label class="field"><span>From</span><input id="library-from" type="date" value="${defaultFrom}"></label><label class="field"><span>To / selected day</span><input id="library-to" type="date" value="${day}"></label>${selected.kind==='class-absence-monthly'?`<label class="field"><span>Month</span><input id="library-month" type="month" value="${day.slice(0,7)}"></label>`:''}${selected.kind==='late-threshold'?'<label class="field"><span>Minimum late marks</span><input type="number" id="library-threshold" value="3" min="1" max="1000"></label><label class="field"><span>Attendance type</span><select id="library-attendance-scope"><option value="class">Class attendance</option><option value="school">School registration</option></select></label>':''}</div><p class="library-format-note">Catalogue format names follow the school list. Available here: CSV download and Print / Save as PDF.</p><div id="library-run-error" class="error" role="alert"></div><div id="library-preview" class="library-preview" aria-live="polite"></div>`,`<small id="library-run-status">Choose filters, then run the report.</small><div class="actions"><button class="btn" data-action="library-run">Run report</button><button class="btn" data-action="library-csv" disabled id="library-csv">Download CSV</button><button class="btn primary" data-action="library-print" disabled id="library-print">Print / Save PDF</button></div>`,'REPORT LIBRARY');
 }
 function params(){const to=$('#library-to').value;return{reportId:selected.id,year:$('#library-year').value,classId:$('#library-class').value,studentId:$('#library-student').value,teacherId:$('#library-teacher').value,from:$('#library-from').value,to,date:to,month:$('#library-month')?.value,threshold:$('#library-threshold')?.value,attendanceScope:$('#library-attendance-scope')?.value,lessonPlans:ui.state().lessons,assignments:ui.state().assignments};}
 async function run(){
  if(running||!selected)return;const q=params(),token=++serial;running=true;result=null;$('#library-run-error').textContent='';$('#library-run-status').textContent='Reading saved records…';$('#library-csv').disabled=$('#library-print').disabled=true;
  try{if(q.month){if(!/^\d{4}-\d{2}$/.test(q.month))throw Error('Choose a valid month.');q.from=q.month+'-01';q.to=shiftDate(new Date(Date.UTC(Number(q.month.slice(0,4)),Number(q.month.slice(5)),1)).toISOString().slice(0,10),-1);}
   if(!isDate(q.from)||!isDate(q.to)||q.from>q.to)throw Error('Choose a valid date range.');
   const response=await fetch('/api/reporting/run',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(q)}),value=await response.json();if(!response.ok)throw Error(value.error||'Could not run this report.');if(token!==serial||!$('#library-preview'))return;result=value;
   $('#library-preview').innerHTML=`<div class="library-preview-meta"><strong>${value.rows.length} records</strong><small>${esc(value.scope)} · ${esc(value.from)} to ${esc(value.to)}</small></div>${value.notes.map(n=>`<p class="notice">${esc(n)}</p>`).join('')}${value.rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${value.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${value.rows.slice(0,100).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${value.rows.length>100?'<p class="muted">Preview shows the first 100 records. Downloads include every matching record.</p>':''}`:'<p class="muted">No matching saved records for this selection.</p>'}`;
   $('#library-run-status').textContent='Report ready · '+value.rows.length+' records';$('#library-csv').disabled=$('#library-print').disabled=false;
  }catch(e){if(token===serial&&$('#library-run-error')){$('#library-run-error').textContent=e.message;$('#library-run-status').textContent='Review the filters and try again.';}}finally{running=false;}
 }
 function record(format){ui.savePreferences({history:[{title:result.title,className:result.scope,detail:result.from+' to '+result.to+' · '+result.rows.length+' rows · '+format,at:new Date().toISOString()},...ui.state().reportHistory].slice(0,50)});const list=$('.library-history');if(list)list.innerHTML='<summary>Recent exports ('+ui.state().reportHistory.length+')</summary>'+ui.state().reportHistory.slice(0,10).map(r=>'<p><strong>'+esc(r.title)+'</strong><br><small>'+esc(r.detail)+' · '+esc(r.at)+'</small></p>').join('');}
 function exportCsv(){if(!result)return;const safe=v=>typeof v==='string'&&/^[=+\-@]/.test(v)?"'"+v:v;ui.download(selected.id+'-'+result.from+'-to-'+result.to+'.csv',csv([result.columns,...result.rows.map(r=>r.map(safe))]));record('CSV');}
 function print(){
  if(!result)return;const target=window.open('','_blank');if(!target){$('#library-run-error').textContent='Allow this site to open the print preview, then try again.';return;}
  const stylesheet=new URL('./report-library-print.css',import.meta.url).href,script=new URL('./report-library-print.mjs',import.meta.url).href,logo=new URL('./assets/wist-report-logo.png',import.meta.url).href;
  const body=result.layout==='table'?`<table><thead><tr>${result.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${result.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:`<div class="label-grid">${result.rows.map(r=>`<section class="address-label">${r.map(v=>`<div>${esc(v)}</div>`).join('')}</section>`).join('')}</div>`;
  target.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(result.title)}</title><link rel="stylesheet" href="${stylesheet}"><script type="module" src="${script}"></script></head><body class="${result.layout}"><header><img src="${logo}" alt="WIST"><div><h1>${esc(result.title)}</h1><p>${esc(result.scope)} · ${esc(result.from)} to ${esc(result.to)} · ${result.rows.length} records</p></div></header>${result.notes.map(n=>`<p class="note">${esc(n)}</p>`).join('')}${body}<footer>Westminster International School Tashkent · Fictional testing data</footer></body></html>`);target.document.close();record('Print / PDF');
 }
 function action(action,t){
  if(!action.startsWith('library-'))return false;
  if(action==='library-favorite'){const ids=ui.state().favorites,id=t.dataset.id;ui.savePreferences({favorites:ids.includes(id)?ids.filter(v=>v!==id):[...ids,id]});paint();}
  if(action==='library-open')configure(t.dataset.id);
  if(action==='library-run')run();if(action==='library-csv')exportCsv();if(action==='library-print')print();
  if(action==='library-expand'||action==='library-collapse'){open=new Set(action==='library-expand'?REPORT_CATEGORIES:[]);paint();}
  return true;
 }
 function input(t){if(t.id==='library-search'){query=t.value;paint();}}
 function change(t){if(t.id==='library-category'){category=t.value;paint();}if(t.id==='library-year'){$('#library-class').innerHTML=options([['','All allocated classes'],...classChoices(t.value).map(c=>[c.id,c.name])]);$('#library-student').innerHTML=options([['','All selected students'],...studentChoices(t.value).map(s=>[s.id,s.name+' · '+s.groupName])]);}if(t.id==='library-class')$('#library-student').innerHTML=options([['','All selected students'],...studentChoices($('#library-year').value,t.value).map(s=>[s.id,s.name+' · '+s.groupName])]);if(t.id?.startsWith('library-')&&$('#library-preview')){result=null;serial++;running=false;$('#library-preview').innerHTML='';$('#library-csv').disabled=$('#library-print').disabled=true;$('#library-run-status').textContent='Filters changed. Run the report again.';}}
 document.addEventListener('toggle',e=>{const name=e.target.dataset?.category;if(name&&!query&&!category){if(e.target.open)open.add(name);else open.delete(name);}},true);
 return{page,action,input,change};
}
